let currentLang='en';
function applyLanguage(lang){
 currentLang=lang; const t=I18N[lang]; document.documentElement.lang=lang; document.documentElement.dir=t.dir; document.body.dir=t.dir;
 const map={langTitle:t.langTitle,langSub:t.langSub,brandTitle:t.brandTitle,brandSub:t.brandSub,mainTitle:t.mainTitle,intro:t.intro,filmWLabel:t.filmWLabel,gapLabel:t.gapLabel,marginLabel:t.marginLabel,settingsNote:t.settingsNote,designsTitle:t.designsTitle,thName:t.name,thWidth:t.width,thHeight:t.height,thQty:t.qty,thRotate:t.rotate,thGroup:t.group,thSeparate:t.separate,addBtn:t.add,resultTitle:t.result,lengthLabel:t.length,metersLabel:t.meters,areaLabel:t.area,countLabel:t.count,filmsLabel:t.films,layoutTitle:t.layout,langChange:lang==='ar'?'تغيير اللغة':lang==='fr'?'Changer de langue':'Change language'};
 Object.entries(map).forEach(([id,txt])=>{const e=document.getElementById(id); if(e)e.textContent=txt;});
 const lc=document.getElementById('langChange'); if(lc) lc.textContent=lang==='ar'?'تغيير اللغة':lang==='fr'?'Changer de langue':'Change language';
 document.getElementById('layout').innerHTML='<div class="empty">'+t.empty+'</div>';
 document.title=t.brandTitle;
 document.querySelectorAll('#rows .del').forEach(b=>b.textContent=t.delete);
 document.querySelectorAll('#rows .name').forEach((e,i)=>{if(!e.value||/^Design \d+$/.test(e.value))e.value=t.design+' '+(i+1);});
}
function showLanguageScreen(){ document.getElementById('langScreen').style.display='flex'; document.querySelector('.wrap').style.display='none'; }
function startApp(lang){ applyLanguage(lang); document.getElementById('langScreen').style.display='none'; document.querySelector('.wrap').style.display='block'; }

let id=0;
function addRow(n='',w='',h='',q=1,rot=true,group='1',separate=false){
 id++;
 const tr=document.createElement('tr'); tr.dataset.id=id;
 tr.innerHTML=`<td><input class="name" value="${n||I18N[currentLang].design+' '+id}"></td>
 <td><input class="w" type="number" min="0.1" step="0.1" value="${w}"></td>
 <td><input class="h" type="number" min="0.1" step="0.1" value="${h}"></td>
 <td><input class="qty" type="number" min="1" step="1" value="${q}"></td>
 <td><input class="rot" type="checkbox" ${rot?'checked':''}></td>
 <td><input class="group" value="${group}" placeholder="1"></td>
 <td><input class="separate" type="checkbox" ${separate?'checked':''}></td>
 <td><button class="del" onclick="this.closest('tr').remove()">${I18N[currentLang].delete}</button></td>`;
 document.getElementById('rows').appendChild(tr);
}
addRow('A','20','30',2,true); addRow('B','15','20',4,true); addRow('C','40','25',1,true);

function getItems(){
 const out=[];
 document.querySelectorAll('#rows tr').forEach(tr=>{
  const name=tr.querySelector('.name').value||'Design';
  const w=+tr.querySelector('.w').value,h=+tr.querySelector('.h').value,q=+tr.querySelector('.qty').value;
  const rot=tr.querySelector('.rot').checked;
  const group=(tr.querySelector('.group')?.value||'1').trim()||'1';
  const separate=tr.querySelector('.separate')?.checked||false;
  if(w>0&&h>0&&q>0) for(let i=1;i<=q;i++) out.push({name,ow:w,oh:h,rot,copy:i,group,separate,rowId:tr.dataset.id});
 });
 return out;
}

/* Shelf/row packing with best-fit row search.
   It is deterministic, fast, and explicitly respects margins and gaps. */
function pack(items, usableW, gap){
  if(!items.length) throw new Error('أضف تصميماً واحداً على الأقل.');

  const EPS=1e-8;
  const pieces=items.map((it,idx)=>({...it,idx,choices:[
    {w:it.ow,h:it.oh,turned:false},
    ...(it.rot && Math.abs(it.ow-it.oh)>EPS ? [{w:it.oh,h:it.ow,turned:true}] : [])
  ]}));

  // Bottom-left 2D packing. Candidate X positions come from the edges of
  // already placed designs, so the algorithm actively fills holes instead of
  // creating artificial full-width rows.
  function attempt(order, prefer){
    const placed=[];

    function overlaps(a,b){
      return a.x < b.x+b.w-EPS && a.x+a.w > b.x+EPS &&
             a.y < b.y+b.h-EPS && a.y+a.h > b.y+EPS;
    }

    function lowestY(x,w,h){
      let y=0;
      while(true){
        let moved=false;
        for(const r of placed){
          const test={x,y,w,h};
          if(overlaps(test,r)){
            y=Math.max(y,r.y+r.h+gap);
            moved=true;
          }
        }
        if(!moved) return y;
      }
    }

    function xCandidates(w){
      const xs=new Set([0]);
      for(const r of placed){
        const right=r.x+r.w+gap;
        const left=r.x-w-gap;
        if(right>=-EPS && right+w<=usableW+EPS) xs.add(Number(right.toFixed(8)));
        if(left>=-EPS && left+w<=usableW+EPS) xs.add(Number(left.toFixed(8)));
      }
      return [...xs].sort((a,b)=>a-b);
    }

    for(const piece of order){
      let best=null;
      for(const c of piece.choices){
        if(c.w>usableW+EPS) continue;
        for(const x of xCandidates(c.w)){
          const y=lowestY(x,c.w,c.h);
          const candidate={...piece,w:c.w,h:c.h,turned:c.turned,x,y};
          const bottom=y+c.h;
          const right=x+c.w;

          // Prefer the lowest bottom edge. For ties, prefer the smallest
          // current maximum height, then the smallest X / least fragmentation.
          const currentMax=placed.length ? Math.max(...placed.map(r=>r.y+r.h)) : 0;
          const newMax=Math.max(currentMax,bottom);
          const score=prefer===0
            ? [bottom,y,x]
            : prefer===1
              ? [newMax,bottom,x]
              : [y,bottom,x];

          if(!best || score.some((v,i)=>v<best.score[i]-EPS &&
              score.slice(0,i).every((q,j)=>Math.abs(q-best.score[j])<EPS))){
            best={candidate,score};
          }
        }
      }
      if(!best) return null;
      placed.push(best.candidate);
    }

    const height=placed.length ? Math.max(...placed.map(r=>r.y+r.h)) : 0;
    return {height,items:placed};
  }

  const baseOrders=[
    [...pieces].sort((a,b)=>Math.max(...b.choices.map(c=>c.w*c.h))-Math.max(...a.choices.map(c=>c.w*c.h))),
    [...pieces].sort((a,b)=>Math.max(...b.choices.map(c=>Math.max(c.w,c.h)))-Math.max(...a.choices.map(c=>Math.max(c.w,c.h)))),
    [...pieces].sort((a,b)=>Math.max(...b.choices.map(c=>c.h))-Math.max(...a.choices.map(c=>c.h))),
    [...pieces].sort((a,b)=>Math.max(...b.choices.map(c=>c.w))-Math.max(...a.choices.map(c=>c.w))),
    [...pieces].sort((a,b)=>Math.min(...b.choices.map(c=>c.w))-Math.min(...a.choices.map(c=>c.w)))
  ];

  // Add reversed and interleaved variants to escape bad greedy choices.
  const orders=[];
  for(const o of baseOrders){
    orders.push(o);
    orders.push([...o].reverse());
    const evens=o.filter((_,i)=>i%2===0), odds=o.filter((_,i)=>i%2===1);
    orders.push([...evens,...odds]);
    orders.push([...odds,...evens]);
  }

  let best=null;
  for(const order of orders){
    for(let prefer=0;prefer<3;prefer++){
      const r=attempt(order,prefer);
      if(r && (!best || r.height<best.height-EPS)) best=r;
    }
  }

  if(!best){
    throw new Error(`يوجد تصميم أكبر من العرض المتاح ${usableW.toFixed(2)} cm. قم بتفعيل التدوير أو صغّر المقاس.`);
  }
  return {rows:[],height:best.height,items:best.items};
}
const LOGO_DATA="";
function buildFilmGroups(items){
 const groups=[];
 const map=new Map();
 items.forEach((item,idx)=>{
   if(item.separate){
     groups.push({key:`separate-${idx}`,label:`${item.name} ${item.copy}`,items:[item]});
   }else{
     const key=`group-${item.group.toLowerCase()}`;
     if(!map.has(key)){ const g={key,label:item.group,items:[]}; map.set(key,g); groups.push(g); }
     map.get(key).items.push(item);
   }
 });
 return groups;
}
function calculate(){
 const filmW=Number(String(document.getElementById('filmW').value).replace(',','.'));
 const gap=Number(String(document.getElementById('gap').value).replace(',','.'));
 const margin=Number(String(document.getElementById('margin').value).replace(',','.'));
 if(!Number.isFinite(filmW)||filmW<=0||!Number.isFinite(gap)||gap<0||!Number.isFinite(margin)||margin<0) return alert('تحقق من قيم العرض والمسافة والهامش.');
 const usableW=filmW-2*margin;
 if(usableW<=0)return alert('الهامش أكبر من عرض Film');
 try{
   const items=getItems();
   if(!items.length) throw new Error(I18N[currentLang].noDesign);
   const groups=buildFilmGroups(items);
   const films=[];
   groups.forEach((g,i)=>{
     const data=pack(g.items,usableW,gap);
     const filmH=data.height+2*margin;
     films.push({...data,filmH,group:g.label,number:i+1});
   });
   const totalH=films.reduce((a,f)=>a+f.filmH,0);
   const totalArea=films.reduce((a,f)=>a+(filmW*f.filmH)/10000,0);
   document.getElementById('length').textContent=totalH.toFixed(2)+' cm';
   document.getElementById('meters').textContent=(totalH/100).toFixed(3)+' m';
   document.getElementById('area').textContent=totalArea.toFixed(4)+' m²';
   document.getElementById('count').textContent=items.length;
   document.getElementById('films').textContent=films.length;
   document.getElementById('detail').textContent=`${I18N[currentLang].detail(usableW,margin,gap,films.length)} — ${currentLang==='ar'?'المجموع يحسب كل Film بشكل مستقل':currentLang==='fr'?'Chaque Film est calculé séparément':'Each Film is calculated separately'}`;
   renderFilms(films,filmW,margin);
 }catch(e){alert(e.message)}
}
function renderFilms(films,fw,margin){
 const box=document.getElementById('layout'); box.innerHTML='';
 const scale=Math.min(8,760/fw);
 films.forEach(f=>{
   const title=document.createElement('div'); title.className='film-title'; title.textContent=I18N[currentLang].filmTitle(f.number,f.filmH); box.appendChild(title);
   const film=document.createElement('div'); film.className='film';
   film.style.width=(fw*scale)+'px'; film.style.height=(f.filmH*scale)+'px';
   const safe=document.createElement('div');
   safe.style.position='absolute'; safe.style.left=(margin*scale)+'px'; safe.style.top=(margin*scale)+'px';
   safe.style.width=((fw-2*margin)*scale)+'px'; safe.style.height=((f.filmH-2*margin)*scale)+'px';
   safe.style.border='1px dashed #999'; safe.style.pointerEvents='none'; film.appendChild(safe);
   const wm=document.createElement('img'); wm.className='logo-watermark'; wm.src="data:image/png;base64,"+LOGO_DATA; film.appendChild(wm);
   f.items.forEach(x=>{
     const d=document.createElement('div'); d.className='item';
     d.style.left=((margin+x.x)*scale)+'px'; d.style.top=((margin+x.y)*scale)+'px';
     d.style.width=(x.w*scale)+'px'; d.style.height=(x.h*scale)+'px';
     d.innerHTML=`${x.name}<br>${x.w.toFixed(1)} × ${x.h.toFixed(1)}${x.turned?' ↻':''}`;
     film.appendChild(d);
   });
   box.appendChild(film);
   const sep=document.createElement('div'); sep.style.height='14px'; box.appendChild(sep);
 });
}